fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| if x == y { '0' } else { '1' })
     .collect()
}

